import {readFileSync} from 'node:fs';
import {baseline,boundary,fromIndex,withRisk,withRelation,withCase,field,reorder} from './builders.mjs';
export const READINESS_PACK_VERSION='PRESCORE-READINESS-RU-GOLDEN-1.0.0';
export function entries(){const es=[];const add=(n,title,input,expected)=>es.push({caseId:`RDY-RU-${String(n).padStart(3,'0')}`,revision:1,title,input,expected:{invariants:true,...expected}});
 add(1,'Complete Index 1000',baseline(),{status:'ASSESSED',level:'HIGH',baseLevel:'HIGH',comparable:true});
 add(2,'LOW risk Index 949',fromIndex(2),{level:'HIGH',summary:{lowRiskCount:1,materialCreditConstraintCount:0}});
 add(3,'850 HIGH boundary',boundary(850),{level:'HIGH',relative:[{other:'RDY-RU-004',field:'level',operator:'GT'}]});
 add(4,'849 MEDIUM boundary',boundary(849),{level:'MEDIUM'});
 add(5,'700 MEDIUM boundary',boundary(700),{level:'MEDIUM',relative:[{other:'RDY-RU-006',field:'level',operator:'GT'}]});
 add(6,'699 LOW boundary',boundary(699),{level:'LOW'});
 add(7,'CRITICAL Index 549',fromIndex(5),{level:'LOW',summary:{criticalRiskCount:1}});
 add(8,'Confirmed global stop',fromIndex(11),{status:'NOT_RATABLE_GLOBAL_STOP',level:'NOT_READY',baseLevel:'NOT_READY',comparable:false,required:[{kind:'GLOBAL_STOP',impact:'BLOCKS_READINESS'}]});
 add(9,'Insufficient core',fromIndex(35),{status:'INSUFFICIENT_DATA',level:'UNKNOWN',comparable:false});
 add(10,'Partial 1000 uncertainty cap',boundary(1000,'PARTIAL'),{status:'PARTIAL',baseLevel:'HIGH',level:'MEDIUM',uncertaintyCapApplied:true,capReasons:['INDEX_PARTIAL']});
 add(11,'Partial 800',boundary(800,'PARTIAL'),{status:'PARTIAL',level:'MEDIUM',uncertaintyCapApplied:false});
 add(12,'Partial 600',boundary(600,'PARTIAL'),{status:'PARTIAL',level:'LOW',uncertaintyCapApplied:false});
 add(13,'LOW confidence caps HIGH',boundary(1000,'CALCULATED','LOW'),{level:'MEDIUM',confidence:'LOW',capReasons:['LOW_INDEX_CONFIDENCE']});
 add(14,'UNKNOWN confidence caps HIGH',boundary(1000,'CALCULATED','UNKNOWN'),{level:'MEDIUM',confidence:'UNKNOWN',capReasons:['UNKNOWN_INDEX_CONFIDENCE']});
 for(const[n,title,code]of [[15,'Data review only','SYN-DATA-REVIEW'],[16,'Missing source','SOURCE_MISSING'],[17,'Stale source','SOURCE_STALE'],[18,'Reconciliation conflict','RECONCILIATION_CONFLICT'],[19,'Missing bank month','BANK_MONTH_MISSING']])add(n,title,withRisk({code,scope:'DATA_REVIEW',domain:'DATA_QUALITY'}),{status:'PARTIAL',level:'MEDIUM',indexValue:1000,summary:{dataReviewCount:1,materialCreditConstraintCount:0},required:[{kind:'DATA_REVIEW',impact:'LIMITS_ASSESSMENT'}],forbidden:[{kind:'CREDIT_RISK'}],relative:[{other:'RDY-RU-001',field:'indexValue',operator:'EQ'}]});
 add(20,'Material Context review',withRelation('REQUIRES_REVIEW'),{status:'PARTIAL',level:'LOW',required:[{kind:'CONTEXT_REVIEW',impact:'LIMITS_ASSESSMENT',sourceCode:'SYN-CONTEXT-synthetic-context'}],capReasons:['MATERIAL_CONTEXT_REVIEW']});
 add(21,'MITIGATES not applied twice',fromIndex(20),{level:'LOW',indexValue:679});
 add(22,'CORROBORATES not applied twice',fromIndex(18),{level:'LOW',indexValue:651});
 add(23,'EXPLAINS has no second effect',fromIndex(22),{level:'LOW',indexValue:665});
 add(24,'Client declaration not a bonus',fromIndex(23),{level:'LOW',indexValue:665});
 for(const[n,title,code,value]of [[25,'Six month company age is neutral','COMPANY_AGE_MONTHS',6],[26,'OKVED is not lender policy','COMPANY_OKVED','41.20'],[27,'Region is not lender policy','COMPANY_REGION','Синтетический регион']]){const x=baseline(),f=x.contextAssessment.facts[0];f.semanticCode=code;f.value=value;add(n,title,x,{level:'HIGH',indexValue:1000});}
 add(28,'No financing case',baseline(),{level:'HIGH',caseDefinitionStatus:'NOT_PROVIDED',relative:[{other:'RDY-RU-001',field:'level',operator:'EQ'}]});
 const partial=withCase({requestedTermMonths:field(null),financingPurpose:field(null),requestedProduct:field(null),urgency:field(null)});
 add(29,'Partial financing case',partial,{level:'HIGH',caseDefinitionStatus:'PARTIAL'});
 add(30,'Defined financing case',withCase(),{level:'HIGH',caseDefinitionStatus:'DEFINED',relative:[{other:'RDY-RU-028',field:'level',operator:'EQ'}]});
 add(31,'Huge requested amount is not capacity',withCase({requestedAmount:field(1000000000)}),{level:'HIGH',relative:[{other:'RDY-RU-030',field:'level',operator:'EQ'}]});
 add(32,'Requested overdraft is not product fit',withCase({requestedProduct:field('OVERDRAFT')}),{level:'HIGH',caseDefinitionStatus:'DEFINED'});
 add(33,'Owner personal BKI excluded',fromIndex(31),{level:'HIGH',forbidden:[{kind:'CREDIT_RISK',sourceCode:'RISK-BKI-CURRENT-OVERDUE'}]});
 add(34,'Guarantorship remains contingent',fromIndex(32),{level:'MEDIUM',status:'PARTIAL',confidence:'UNKNOWN',indexValue:1000,forbidden:[{kind:'CREDIT_RISK'}],capReasons:['INDEX_PARTIAL','UNKNOWN_INDEX_CONFIDENCE']});
 add(35,'Bank guarantee remains contingent',fromIndex(33),{level:'MEDIUM',status:'PARTIAL',confidence:'UNKNOWN',indexValue:1000,forbidden:[{kind:'CREDIT_RISK'}],capReasons:['INDEX_PARTIAL','UNKNOWN_INDEX_CONFIDENCE']});
 add(36,'Current overdue with zero historical days',fromIndex('IDX-RU-DEFECT-001'),{level:'MEDIUM',required:[{kind:'CREDIT_RISK',sourceCode:'RISK-BKI-CURRENT-OVERDUE'}],forbidden:[{sourceCode:'RISK-BKI-HISTORICAL-DELINQUENCY'}],defect:true});
 add(37,'Reordered multi-risk input',reorder(fromIndex(40)),{level:'LOW',relative:[{other:'RDY-RU-040',field:'output',operator:'EQ'}]});
 add(38,'Immutable upstream inputs',fromIndex(27),{level:'LOW',immutable:true});
 const bad=baseline();bad.prescoreIndex.companyInn='9900000002';add(39,'Malformed company fails safely',bad,{invalid:'INDEX_COMPANY_OR_ASOF'});
 add(40,'Real canonical multi-risk pipeline',fromIndex(40),{level:'LOW'});
 es.push({caseId:'RDY-RU-DEFECT-001',revision:1,title:'Permanent historical-zero overdue regression chain',input:fromIndex('IDX-RU-DEFECT-001'),expected:{invariants:true,level:'MEDIUM',defect:true,required:[{sourceCode:'RISK-BKI-CURRENT-OVERDUE',impact:'REFLECTED_IN_INDEX'}],forbidden:[{sourceCode:'RISK-BKI-HISTORICAL-DELINQUENCY'}]}});
 return es;}
export function loadReadinessPack(){return {version:READINESS_PACK_VERSION,entries:entries(),fingerprints:JSON.parse(readFileSync(new URL('./fingerprints-stage5.json',import.meta.url),'utf8'))};}
